import{_ as o,o as t,c as i,f as a}from"./chunks/framework.o8v22TzC.js";const r="/images/heroes-olden-era/01.jpg",u=JSON.parse(`{"title":"Heroes of Might and Magic: Olden Era | How Hero Promotion Works","description":"Hero promotion is one of the most planning-heavy systems in Olden Era. Here's how it works and why your skill choices early on matter more than you might think.","frontmatter":{"title":"Heroes of Might and Magic: Olden Era | How Hero Promotion Works","description":"Hero promotion is one of the most planning-heavy systems in Olden Era. Here's how it works and why your skill choices early on matter more than you might think.","date":"2025-05-15","category":"Player Insights","tags":["hero","promotion","skills","progression","tips"],"featured":false,"order":9,"cover":"/images/heroes-olden-era/01.jpg","gameHeader":"/images/heroes-olden-era/header.jpg","head":[["meta",{"property":"og:title","content":"How Hero Promotion Works | Scroll Tome"}],["meta",{"property":"og:description","content":"Hero promotion is one of the most planning-heavy systems in Olden Era. Here's how it works and why your skill choices early on matter more than you might think."}],["link",{"rel":"canonical","href":"https://scrolltome.com/guide/09-hero-promotion-guide"}],["link",{"rel":"canonical","href":"https://scrolltome.com/guide/09-hero-promotion-guide"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Heroes of Might and Magic: Olden Era | How Hero Promotion Works\\",\\"description\\":\\"Hero promotion is one of the most planning-heavy systems in Olden Era. Here's how it works and why your skill choices early on matter more than you might think.\\",\\"datePublished\\":\\"2025-05-15\\",\\"dateModified\\":\\"2025-05-15\\",\\"url\\":\\"https://scrolltome.com/guide/09-hero-promotion-guide\\",\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Scroll Tome\\",\\"url\\":\\"https://scrolltome.com\\"},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://scrolltome.com/guide/09-hero-promotion-guide\\"}}"]]},"headers":[],"relativePath":"guide/09-hero-promotion-guide.md","filePath":"guide/09-hero-promotion-guide.md"}`),n={name:"guide/09-hero-promotion-guide.md"};function s(l,e,h,m,p,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<p>A lot of players don&#39;t notice the promotion system until mid-game, and by then they&#39;ve already made skill choices that lock them out of the path they wanted. Worth understanding early.</p><hr><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Click the class icon on your hero&#39;s screen. You&#39;ll see two promotion options — each one is a different direction you can take that hero&#39;s identity. One might lean into combat, the other into spellcasting, or utility, depending on the base class.</p><p>To unlock either promotion, you need to meet a set of five specific skill requirements. Each of those five skills has to be leveled to Rank 3 — the maximum individual skill tier. Once all five are maxed, the promotion becomes available.</p><p>That&#39;s the system. It&#39;s simple on paper.</p><hr><h2 id="why-it-s-actually-hard" tabindex="-1">Why it&#39;s actually hard <a class="header-anchor" href="#why-it-s-actually-hard" aria-label="Permalink to &quot;Why it&#39;s actually hard&quot;">​</a></h2><p>Your hero has a limited number of skill slots. You can&#39;t just learn every skill and wait — you&#39;ll run out of room before you get close to meeting the requirements for anything.</p><p>This means every skill you pick up is a commitment. Take a skill that isn&#39;t part of any promotion path you care about, and you&#39;ve spent a slot that could have been reserved for something that matters. Do it two or three times and suddenly the five skills you need won&#39;t all fit, even if you theoretically have the levels to rank them up.</p><p>The constraint is the point. Promotions are meant to be something you build toward intentionally, not something that happens by accident.</p><p><img src="'+r+'" alt="Late-game combat — what a properly promoted hero&#39;s army looks like in action"></p><hr><h2 id="what-this-means-in-practice" tabindex="-1">What this means in practice <a class="header-anchor" href="#what-this-means-in-practice" aria-label="Permalink to &quot;What this means in practice&quot;">​</a></h2><p>Before you start leveling a hero seriously, look at both promotion paths for their class and decide which one you&#39;re aiming for. Then check which five skills that path needs.</p><p>From that point, treat those five skills as your core priority. When you&#39;re offered new skills on level-up, always ask whether the option fits your path or burns a slot you need. Passing on a skill that looks good in isolation is often the right call.</p><p>The other thing worth knowing: the two promotion paths for the same class will often share some skill requirements and diverge on others. If you&#39;re early enough, it&#39;s possible to keep both options open for a while by prioritizing the overlapping skills first. At some point you&#39;ll have to commit, but delaying that decision gives you more flexibility as you figure out what you actually need.</p><hr><p>The system rewards players who look ahead. If you&#39;re investing in a hero for the long run — especially one you plan to carry into the late game or PvP — knowing their promotion path before you start assigning skills is one of the better uses of five minutes at the start of a map.</p>',19)])])}const y=o(n,[["render",s]]);export{u as __pageData,y as default};
